#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll INF = (ll)1e18;
int sz;

ll query(const vector<ll> &t, int l, int r) {  // min over [l, r)
    ll ans = INF;
    for (l += sz, r += sz; l < r; l >>= 1, r >>= 1) {
        if (l & 1) ans = min(ans, t[l++]);
        if (r & 1) ans = min(ans, t[--r]);
    }
    return ans;
}

void update(vector<ll> &t, int pos, ll val) {
    pos += sz;
    t[pos] = min(t[pos], val);
    for (pos >>= 1; pos; pos >>= 1) t[pos] = min(t[2 * pos], t[2 * pos + 1]);
}

int main() {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) return 0;
    vector<ll> a(n);
    for (auto &x : a) scanf("%lld", &x);
    vector<ll> v(a);
    sort(v.begin(), v.end());
    v.erase(unique(v.begin(), v.end()), v.end());
    int m = v.size();
    sz = 1;
    while (sz < m) sz *= 2;
    vector<ll> prev(n, 0), cur(n);
    for (int len = 2; len <= k; len++) {
        // lo holds dp[j]-a[j] (for a[j] <= a[i]), hi holds dp[j]+a[j] (for a[j] >= a[i]).
        vector<ll> lo(2 * sz, INF), hi(2 * sz, INF);
        for (int i = 0; i < n; i++) {
            ll x = a[i];
            int t = lower_bound(v.begin(), v.end(), x) - v.begin();
            cur[i] = min(query(lo, 0, t + 1) + x, query(hi, t, m) - x);
            if (prev[i] < INF) { update(lo, t, prev[i] - x); update(hi, t, prev[i] + x); }
        }
        swap(prev, cur);
    }
    printf("%lld\n", *min_element(prev.begin(), prev.end()));
