import java.io.*;
import java.util.*;

public class Main {
    static final long INF = (long) 1e18;
    static int sz;

    static long query(long[] t, int l, int r) { // min over [l, r)
        long ans = INF;
        for (l += sz, r += sz; l < r; l >>= 1, r >>= 1) {
            if ((l & 1) == 1) ans = Math.min(ans, t[l++]);
            if ((r & 1) == 1) ans = Math.min(ans, t[--r]);
        }
        return ans;
    }

    static void update(long[] t, int pos, long val) {
        pos += sz;
        t[pos] = Math.min(t[pos], val);
        for (pos >>= 1; pos > 0; pos >>= 1) t[pos] = Math.min(t[2 * pos], t[2 * pos + 1]);
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.resetSyntax();
        st.wordChars('!', '~');
        st.whitespaceChars(0, ' ');
        st.nextToken(); int n = Integer.parseInt(st.sval);
        st.nextToken(); int k = Integer.parseInt(st.sval);
        long[] a = new long[n];
        for (int i = 0; i < n; i++) { st.nextToken(); a[i] = Long.parseLong(st.sval); }
        long[] v = Arrays.stream(a).sorted().distinct().toArray();
        int m = v.length;
        sz = 1;
        while (sz < m) sz *= 2;
        long[] prev = new long[n], cur = new long[n];
        for (int len = 2; len <= k; len++) {
            // lo holds dp[j]-a[j] (for a[j] <= a[i]), hi holds dp[j]+a[j] (for a[j] >= a[i]).
            long[] lo = new long[2 * sz], hi = new long[2 * sz];
            Arrays.fill(lo, INF);
            Arrays.fill(hi, INF);
            for (int i = 0; i < n; i++) {
                long x = a[i];
                int t = Arrays.binarySearch(v, x);
                cur[i] = Math.min(query(lo, 0, t + 1) + x, query(hi, t, m) - x);
                if (prev[i] < INF) { update(lo, t, prev[i] - x); update(hi, t, prev[i] + x); }
            }
            long[] tmp = prev; prev = cur; cur = tmp;
        }
        long ans = INF;
        for (long x : prev) ans = Math.min(ans, x);
        System.out.println(ans);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"slices"
	"sort"
)

const INF = int64(1e18)

var sz int

func query(t []int64, l, r int) int64 { // min over [l, r)
	ans := INF
	for l, r = l+sz, r+sz; l < r; l, r = l>>1, r>>1 {
		if l&1 == 1 {
			ans = min(ans, t[l])
			l++
		}
		if r&1 == 1 {
			r--
			ans = min(ans, t[r])
		}
	}
	return ans
}

func update(t []int64, pos int, val int64) {
	pos += sz
	t[pos] = min(t[pos], val)
	for pos >>= 1; pos > 0; pos >>= 1 {
		t[pos] = min(t[2*pos], t[2*pos+1])
	}
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, k int
	fmt.Fscan(in, &n, &k)
	a := make([]int64, n)
	for i := range a {
		fmt.Fscan(in, &a[i])
	}
	v := slices.Clone(a)
	slices.Sort(v)
	v = slices.Compact(v)
	m := len(v)
	sz = 1
	for sz < m {
		sz *= 2
	}
	prev, cur := make([]int64, n), make([]int64, n)
	lo, hi := make([]int64, 2*sz), make([]int64, 2*sz)
	for length := 2; length <= k; length++ {
		// lo holds dp[j]-a[j] (for a[j] <= a[i]), hi holds dp[j]+a[j] (for a[j] >= a[i]).
		for i := range lo {
			lo[i], hi[i] = INF, INF
		}
		for i, x := range a {
			t := sort.Search(m, func(p int) bool { return v[p] >= x })
			cur[i] = min(query(lo, 0, t+1)+x, query(hi, t, m)-x)
			if prev[i] < INF {
				update(lo, t, prev[i]-x)
				update(hi, t, prev[i]+x)
			}
		}
		prev, cur = cur, prev
	}
	fmt.Println(slices.Min(prev))
}
